const D = { energy: .62, scale: 1, detail: .5, speed: 1, density: .55, hue: 225, x: .5, y: .5, style: 'electric', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clamp = (v,a,b)=> v<a?a:(v>b?b:v);

// ---- coarse escape-time buffer (per-pixel Julia iteration, image()-upscaled) ----
const BW = 185, BH = Math.max(64, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }

// ---- seed-dependent morph path + framing (rebuild only when seed changes) ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
  S.ph1 = fr(1)*6.2831;          // primary orbit phase
  S.ph2 = fr(2)*6.2831;          // secondary epicycle phase
  S.rBase = 0.70 + fr(3)*0.09;   // c-orbit radius near the Mandelbrot boundary -> connected morphing Julias
  S.rot = (fr(4)-0.5)*0.5;       // view rotation
  S.px0 = (fr(5)-0.5)*0.10;      // view pan jitter
  S.py0 = (fr(6)-0.5)*0.10;
}

// hsv h(deg) s,v(0..1) -> rgb(0..1)
function hsv(h,s,v){ h=((h%360)+360)%360; const c=v*s, x=c*(1-Math.abs((h/60)%2-1)), m=v-c; let r,g,b;
  if(h<60){r=c;g=x;b=0;}else if(h<120){r=x;g=c;b=0;}else if(h<180){r=0;g=c;b=x;}else if(h<240){r=0;g=x;b=c;}else if(h<300){r=x;g=0;b=c;}else{r=c;g=0;b=x;}
  return [r+m,g+m,b+m]; }

// ---- animated params (read every frame) ----
const style = P.style;
const sec = K.section;
const hDrift = Math.sin(sec*0.7 + K.t*0.015)*16;      // per-section palette drift
const hb = P.hue + hDrift;
const expo = 0.46 + P.energy*0.82 + K.intensity*0.30 + A.rms*0.5;
const dens = P.density;
const maxIter = Math.floor(36 + P.detail*84 + K.intensity*20);   // complexity builds with intensity
const invLog2 = 1/Math.log(2);
const cyc = K.t*0.12;                                  // psychedelic band drift

// ---- build a 256-entry exterior palette LUT (cheap; rebuilt per frame so it drifts) ----
if (!S.lut) S.lut = new Float32Array(256*3);
const lut = S.lut;
for (let k=0;k<256;k++){
  const m = k/255; let r,g,b;
  if (style==='ember'){                                // blackbody: red -> orange -> yellow -> white
    r = clamp(Math.pow(m,0.55)*1.55, 0,1);
    g = clamp((m-0.28)*1.75, 0,1);
    b = clamp((m-0.62)*2.3, 0,1);
    r = r*0.94 + 0.05;                                 // dim ember floor (never dead black)
  } else if (style==='psychedelic'){                   // full-spectrum drifting bands
    const c = hsv((m*(2.2+dens*5)+cyc+hb/360)*360, 0.85, clamp(0.2+m*0.76,0,1));
    r=c[0]; g=c[1]; b=c[2];
  } else if (style==='ice'){                            // cyan/white glacial
    r = clamp(m*m*1.05+0.05, 0,1);
    g = clamp(0.16+m*0.9, 0,1);
    b = clamp(0.34+m*0.72, 0,1);
  } else if (style==='etched'){                         // copperplate contours: white lines on graded ground
    const lines = m*(5+dens*18);
    const f = lines-Math.floor(lines); const edge=Math.min(f,1-f);
    const ink = clamp((0.11-edge)/0.08,0,1);
    const v = ink*0.95 + m*0.13 + 0.02;
    r=v*0.99; g=v*0.98; b=v;
  } else {                                              // electric (default): blue/violet field -> gold filaments
    const baseV = 0.44 + 0.55*m;
    const baseS = clamp(0.9 - m*0.45, 0,1);
    const cb = hsv(hb + m*40, baseS, baseV);
    const gold = Math.pow(m, 3.2);
    r = clamp(cb[0]*(1-gold*0.85) + gold*1.0, 0,1);
    g = clamp(cb[1]*(1-gold*0.85) + gold*0.80, 0,1);
    b = clamp(cb[2]*(1-gold*0.85) + gold*0.30, 0,1);
  }
  const o=k*3; lut[o]=r; lut[o+1]=g; lut[o+2]=b;
}

// ---- morphing c: incommensurate epicycle near the M-boundary -> perpetual dendrite/rabbit/dragon/spiral morph ----
const w1 = K.t*(0.028 + P.speed*0.045) + S.ph1;
const w2 = K.t*(0.017 + P.speed*0.026) + S.ph2;
const R = S.rBase + 0.05*Math.sin(sec*0.7 + K.t*0.02) + A.bass*0.03;
const cr = R*Math.cos(w1) + 0.06*Math.cos(w2*2.0 + 1.1);
const ci = R*Math.sin(w1) + 0.06*Math.sin(w2*2.0 - 0.4);

// ---- view: slow zoom-breathe + pan drift for extra life ----
const zb = 1 + 0.08*Math.sin(K.t*0.04) + A.rms*0.14;
const halfY = 1.6/(P.scale*zb), halfX = halfY*(BW/BH);
const vx = (P.x-0.5)*1.2 + S.px0 + Math.sin(K.t*0.011)*0.05;
const vy = (P.y-0.5)*1.2 + S.py0 + Math.cos(K.t*0.009)*0.05;
const cosR = Math.cos(S.rot), sinR = Math.sin(S.rot);

const g = S.g; g.loadPixels(); const px = g.pixels;
for (let j=0;j<BH;j++){
  const dyc = (j/(BH-1)-0.5)*2*halfY;
  for (let i=0;i<BW;i++){
    const dxc = (i/(BW-1)-0.5)*2*halfX;
    let zr = vx + dxc*cosR - dyc*sinR;
    let zi = vy + dxc*sinR + dyc*cosR;
    let n=0, trap=1e9, m2=zr*zr+zi*zi;
    while (n<maxIter && m2<=256){
      const nr = zr*zr - zi*zi + cr;
      zi = 2*zr*zi + ci; zr = nr;
      m2 = zr*zr+zi*zi;
      if (m2<trap) trap=m2;
      n++;
    }
    let r,g2,b;
    if (n>=maxIter){
      // interior: dark-tinted orbit-trap glow (never pure black)
      const tv = clamp(1 - Math.sqrt(trap)*0.9, 0, 1);
      if (style==='ember'){ const v=(0.05+tv*0.5)*expo*0.8; r=clamp(v*1.1,0,1); g2=clamp(v*0.42,0,1); b=clamp(v*0.12,0,1); }
      else if (style==='psychedelic'){ const c=hsv((tv*1.5+cyc)*360+hb,0.8,clamp((0.06+tv*0.5)*expo*0.8,0,1)); r=c[0];g2=c[1];b=c[2]; }
      else if (style==='ice'){ const v=(0.05+tv*0.5)*expo*0.85; r=clamp(v*0.5,0,1); g2=clamp(v*0.85,0,1); b=clamp(v*1.1+0.03,0,1); }
      else if (style==='etched'){ const h=((tv*6)%1)<0.5?0.13:0.07; r=h*0.99; g2=h*0.98; b=h; }
      else { const v=clamp((0.13+tv*0.55)*expo,0,1); const c=hsv(hb-8, clamp(0.85-tv*0.4,0,1), v); r=c[0];g2=c[1];b=c[2]; }
    } else {
      // exterior: smooth continuous iteration -> palette LUT
      const mag=Math.sqrt(m2);
      let sm = n + 1 - Math.log(Math.log(mag))*invLog2;
      if (sm<0) sm=0;
      let m = sm/maxIter; if (m>1) m=1; if (m<0) m=0;
      const idx = (m*255)|0; const o=idx*3;
      const ex = clamp(expo,0,1.8);
      r = clamp(lut[o]*ex,0,1); g2 = clamp(lut[o+1]*ex,0,1); b = clamp(lut[o+2]*ex,0,1);
    }
    const o=4*(j*BW+i);
    px[o]=r*255; px[o+1]=g2*255; px[o+2]=b*255; px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();
// audio-reactive filament bloom (partial ADD wash; zero during validation; never a full-frame flash)
if ((A.bass>0.02 || A.treble>0.02 || A.rms>0.02) && style!=='etched'){
  push(); blendMode(ADD); noStroke();
  const glow = (A.bass*0.5 + A.treble*0.35 + A.rms*0.35)*P.energy;
  fill((hb+30)%360, 45, 100, clamp(glow*20,0,22));
  rect(0,0,width,height);
  blendMode(BLEND); pop();
}
